select 'lead_events_never_attempted' as metric, count(*)::text as value from public.raw_events re where re.canonical_entity = 'lead_event' and not exists (select 1 from public.normalization_records nr where nr.raw_event_id = re.id) union all select 'normalization_status:' || coalesce(s.status::text, 'null'), count(*)::text from public.normalization_records s where s.canonical_entity::text = 'lead_event' group by s.status union all select 'rejected_by_code:' || coalesce(r.code, 'unparsed'), count(*)::text from (select substring(processing_error from '"code":"([^"]+)"') as code from public.normalization_records where status = 'rejected') r group by r.code union all select 'normalization_rows_minus_distinct_raw_events', (count(*) - count(distinct raw_event_id))::text from public.normalization_records union all select 'canonical_lead_event_rows_minus_distinct_raw_events', (count(*) - count(distinct raw_event_id))::text from public.canonical_lead_event_records union all select 'canonical_lead_event_rows', count(*)::text from public.canonical_lead_event_records order by 1;
